import type { ReactElement } from "react";
import { SectionHeader } from "../components/SectionHeader";
import { portfolioData, visibleSubDetails } from "../data";

// 왼쪽은 재직 기간, 오른쪽 타임라인은 회사 정보와 프로젝트별 주요 업무 제목을 보여준다.
export function CareerSection(): ReactElement {
  const { profile } = portfolioData;

  return (
    <section className="scroll-mt-16 bg-surface" id="career">
      <div className="mx-auto max-w-[880px] px-4 py-16 sm:px-6 md:py-24">
        <SectionHeader title="경력" />
        <div className="grid gap-4 md:grid-cols-[170px_minmax(0,1fr)] md:gap-12">
          <p className="break-keep text-body-md font-semibold md:pt-1.5">
            {profile.careerPeriod}
            <span className="mt-1 block font-normal text-muted">{profile.experience}</span>
          </p>
          <div className="relative border-l border-border pl-8">
            <span className="absolute -left-1.5 top-3 size-3 rounded-full bg-primary ring-4 ring-surface" aria-hidden="true" />
            <h3 className="text-heading-2">{profile.employer}</h3>
            <p className="mt-2 break-keep text-body-md font-semibold">
              {profile.company} · {profile.role} · {profile.position}
            </p>
            <p className="mt-2 break-keep text-body-md text-ink-secondary">{portfolioData.careerIntro}</p>
            <div className="mt-8 grid gap-8">
              {portfolioData.projectGroups.map((group) => (
                <div key={group.id}>
                  <h4 className="break-keep text-title">{group.title}</h4>
                  <ul className="mt-3 list-disc space-y-2 pl-5 text-body-md text-ink-secondary">
                    {visibleSubDetails(group)
                      .filter((subDetail) => !subDetail.hiddenInCareer)
                      .map((subDetail) => (
                        <li className="break-keep" key={subDetail.id}>
                          {subDetail.title}
                        </li>
                      ))}
                  </ul>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
