import { lazy, Suspense, type ReactElement } from "react";
import { ArrowRight } from "lucide-react";
import { Badge } from "../../components/ui/badge";
import { SectionHeader } from "../components/SectionHeader";
import { portfolioData, visibleSubDetails } from "../data";
import { useProjectModal } from "../hooks/useProjectModal";

// 모달 코드와 캡처는 첫 화면에 필요 없어 열 때 받는다.
const ProjectDetailModal = lazy(() =>
  import("../components/ProjectDetailModal").then((module) => ({ default: module.ProjectDetailModal })),
);

// 카드에는 대표 수치와 가장 기여도 높은 작업만 두고, 나머지는 모달에서 읽는다.
export function ProjectListSection(): ReactElement {
  const { activeId, open, select, close } = useProjectModal();

  return (
    <section className="mx-auto max-w-[1120px] scroll-mt-16 px-4 py-16 sm:px-6 md:py-24" id="projects">
      <SectionHeader title="프로젝트" />
      <div className="grid gap-14">
        {portfolioData.projectGroups.map((group) => (
          <div key={group.id}>
            <h3 className="break-keep text-[28px] font-bold leading-[1.25] tracking-[-0.75px] md:text-[32px]">{group.title}</h3>
            <p className="mt-3 max-w-[720px] whitespace-pre-line break-keep text-body-md text-muted">{group.text}</p>
            <div className="mt-4 flex max-w-[720px] flex-wrap gap-1.5">
              {group.tags.map((tag) => (
                <Badge variant="muted" className="bg-surface-strong" key={tag}>
                  {tag}
                </Badge>
              ))}
            </div>
            <ul className="mt-6 grid gap-5 md:grid-cols-2">
              {visibleSubDetails(group).map((subDetail) => {
                return (
                  <li key={subDetail.id}>
                    <button
                      type="button"
                      className="group flex h-full w-full flex-col rounded-lg border border-border bg-surface p-5 text-left shadow-soft transition-transform hover:-translate-y-0.5 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent sm:p-6"
                      onClick={() => open(subDetail.id)}
                    >
                      <span className="flex items-start justify-between gap-3">
                        <span className="break-keep text-heading-3">
                          <span className="mr-2 text-subtle">{subDetail.number}</span>
                          {subDetail.title}
                        </span>
                        <ArrowRight className="mt-1 shrink-0 text-accent transition-transform group-hover:translate-x-0.5" size={20} aria-hidden="true" />
                      </span>
                      <strong className="mt-4 block break-keep rounded-md bg-[color:var(--accent-soft)] px-3.5 py-2.5 text-body-md font-bold text-[color:var(--accent-strong)]">
                        {subDetail.cardMetric}
                      </strong>
                      <span className="mt-4 block break-keep text-body-md text-ink-secondary">{subDetail.cardSummary}</span>
                    </button>
                  </li>
                );
              })}
            </ul>
          </div>
        ))}
      </div>
      {activeId && (
        <Suspense fallback={null}>
          <ProjectDetailModal subDetailId={activeId} onSelect={select} onClose={close} />
        </Suspense>
      )}
    </section>
  );
}
